-- PRIVATE CANDIDATE ONLY. NOT APPLIED OR RUNTIME-REHEARSED.
-- Finite manual decisions, not provider response recovery. No baseline/source,
-- paid reservation, source approval, public event or notification write.
create table public.program_text_smart_legacy_manual_reviews (
 id uuid primary key default gen_random_uuid(),source_id uuid not null,epoch uuid not null,policy text not null,
 context_hash text not null check(context_hash~'^[a-f0-9]{64}$'),request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),originals_hash text not null check(originals_hash~'^[a-f0-9]{64}$'),
 request jsonb not null,authority_before jsonb not null,verified_originals jsonb not null,
 actor_id uuid not null,approved_at timestamptz not null default clock_timestamp(),
 unique(source_id,policy),check(policy='awardping.smart-legacy36-manual-text-reconciliation.v1')
);
create table public.program_text_smart_legacy_manual_entries (
 id uuid primary key default gen_random_uuid(),review_id uuid not null references public.program_text_smart_legacy_manual_reviews(id)on delete restrict,
 candidate_id uuid not null unique references public.shared_award_visual_review_candidates(id)on delete restrict,
 original_candidate jsonb not null,original_pg_hash text not null check(original_pg_hash~'^[a-f0-9]{64}$'),original_xmin text not null,
 decision text not null check(decision='no_program_detail_change'),reason text not null check(private.awardping_program_utf16_length(btrim(reason))between 20 and 2000)
);
alter table public.program_text_smart_legacy_manual_reviews enable row level security;
alter table public.program_text_smart_legacy_manual_entries enable row level security;
revoke all on public.program_text_smart_legacy_manual_reviews,public.program_text_smart_legacy_manual_entries from public,anon,authenticated,service_role;
grant select on public.program_text_smart_legacy_manual_reviews,public.program_text_smart_legacy_manual_entries to service_role;
create function private.awardping_smart_legacy_manual_immutable()returns trigger language plpgsql set search_path=''as $$
begin raise exception 'SMART manual reconciliation history is immutable.'using errcode='23514';end;$$;
create trigger smart_legacy_manual_reviews_immutable before update or delete on public.program_text_smart_legacy_manual_reviews
 for each row execute function private.awardping_smart_legacy_manual_immutable();
create trigger smart_legacy_manual_reviews_no_truncate before truncate on public.program_text_smart_legacy_manual_reviews
 for each statement execute function private.awardping_smart_legacy_manual_immutable();
create trigger smart_legacy_manual_entries_immutable before update or delete on public.program_text_smart_legacy_manual_entries
 for each row execute function private.awardping_smart_legacy_manual_immutable();
create trigger smart_legacy_manual_entries_no_truncate before truncate on public.program_text_smart_legacy_manual_entries
 for each statement execute function private.awardping_smart_legacy_manual_immutable();

