","text_sha256":"23e160292a206d4a12bc2b1ee610ba88fd809fe5c07723a338ac93c072f43af1","raw_text_sha256":"96590b84a0e540b1a0bdeef97055f56bf104ada472894fbc55414a63deca2339","raw_text_bytes":3348,"metadata_sha256":"7e24795c68e680a518f3bfb8416b902b2770e22b9a41b42ac43a7c08adcd2b48","metadata_bytes":22059},{"reference_sha256":"98b5b5405507db51f3e6baf432f5dcc24cc429e27d009ebaea4b4ec42d0f5eeb","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-07T00:54:43.016Z","text_sha256":"41c9f7f5297de175f65f136c47dc4a349a0cdd1f7448c58371dc61bc3e921566","raw_text_sha256":"080255491814a588f9584fc1f0284bc76bb54c5ce5f1fd91ea65dd5874c4cde8","raw_text_bytes":3348,"metadata_sha256":"0d16b1b2f4a440c763f9235f69e9cd2f8d7475e5975fbc69539a6277e404b543","metadata_bytes":22057},{"reference_sha256":"1de704ef53a16155d73c9d6f6a35bb32c9bce7bbdf65e8ae0390a42619d2aa8e","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-08T00:56:02.098Z","text_sha256":"003a3217d2941f47d59bb9b6dd07b5446951444a241952d6a3570f0f75e4e2c0","raw_text_sha256":"fca717325b945a233b4c778a4683717beb8801ae4a78315de95c37962b9fcf3a","raw_text_bytes":3348,"metadata_sha256":"b7955f140ca7127304f0e9e9b48bf0b5036441ec7e90e7cdd630ba3045026c39","metadata_bytes":22058},{"reference_sha256":"d0e796d2c52b904be3b0c8f930a1015868004660428c51eff62fc29d91006c6e","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-09T00:54:01.922Z","text_sha256":"3d94c57156704efebce4680b0b980c0cac2f320e48e40211c9a4e9e54645e2d1","raw_text_sha256":"f810b69ff81f77e54bd2f6b2216f561722bed08991f3f9b4828bfb4e94764d52","raw_text_bytes":3348,"metadata_sha256":"83c8c1ffb574506643f019e246db33086885a2933e23f3355fe7c65c510c19f3","metadata_bytes":22080},{"reference_sha256":"08449d3203d00fee1f51e657e5b76043d33e24f9698d5a17f8fa014a5bd6ebc8","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-10T00:48:24.519Z","text_sha256":"34ce2fe0a083a4b04ae5122ea9784f522c5d56d18f9090dc477d6c73c0dfc0ad","raw_text_sha