etadata_sha256":"5993c027f86287c1033d1aa38cd4f7eb18f1080d4121f13f1b1132b068770533","metadata_bytes":22058},{"reference_sha256":"189af7aa26871bd89785e3c70d84252af7336ef2232ea1a3f4747c0dc39436de","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-15T00:48:16.903Z","text_sha256":"3f1a2be5841de433499b8502cf7ee8258cb6c460bcacf34baf51dcacfe4a0584","raw_text_sha256":"d48ac6d651006bf36e211a7c8eb08687a418fc672e26a4fc52d537bd7797de25","raw_text_bytes":3348,"metadata_sha256":"9a08dcce48c007a41f9418b3a7e615a98a29090282e45829345dbb2a1b1e0b2f","metadata_bytes":22058},{"reference_sha256":"538b84199df9f717d37458f63cdbf51219196615f5f1a63cc9d33141a70020d7","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-16T00:51:03.379Z","text_sha256":"083e0fc5ac391a1892e6e06cbfd1e03d7d2e83be63b84e93c483e82f3fe76fe1","raw_text_sha256":"2f0a3211a2033a948836351ff4f4bb33c2fa38c4502dfd68b6f5b2b89443bfe4","raw_text_bytes":3348,"metadata_sha256":"bf5913c12721594be7788a3bea2ca4ed3ef91fba43751fb409225a5c2f6a3260","metadata_bytes":22058},{"reference_sha256":"afc6f23e83e995cc2cdaf452c5743435ccfa9756681bbd35003e8d0da0ea3e87","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-17T00:50:55.646Z","text_sha256":"3bd453a0a2d3211984cfca0ca3834ca3195e2f54c27df16f1b552acc3ce05a81","raw_text_sha256":"7a077d0260efc49670f4330788758d64fcc0967e7fd85415eb3233c158e1bcdc","raw_text_bytes":3348,"metadata_sha256":"1bfa259de0646c8971924e5a74135b58fbc1240d3a18af35c01dab9a6f17ece5","metadata_bytes":22059},{"reference_sha256":"0f67f94d70a9f9bede255877cfef71509b581b4c16c2568e606311681ac631dd","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-18T00:43:02.834Z","text_sha256":"7ab2f61915a3e65345fecc39fa4180a659f6d6323312366b4f183c42d09b6226","raw_text_sha256":"771dfdd5550d02857f2f68295050bbcf1e2701e942595ffb27974ab158b41d64","raw_text_bytes":3348,"metadata_sha256":"dc845ea228c2f21a793b79217107a0165aad1102fcdce59c3efb7016ea20aaab","metadata_bytes":22058},{"reference_sha256":"df0ad8a9b888d9ddb2401a3d3d3f1fc06b760b00fd27af852b2130cdcb6d5b35","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-19T00:43:03.155Z","text_sha256":"53bba5af26f42d1728cc1fd323828123decfb64d944e95d650c0f2c727565b35","raw_text_sha256":"8e3785828a6cf2d4ffdce1c2c0f09f26f77df465d4079dccd735f33d53d045e1","raw_text_bytes":3348,"metadata_sha256":"9b6cf20eb8ff1b4286f21b7729907cb6d769aa90c9c88db2f215136768199ad6","metadata_bytes":23031},{"reference_sha256":"6a7f38786c675505e5dfd8bbfdba03a934444a96e6e0df87454c3e3895a58474","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-20T00:44:42.040Z","text_sha256":"6483cb0d06e59afe346df241369806222807de557b4f1e87d05417c76da74652","raw_text_sha256":"ce6ec0f500e9c9cac2cb11f9e736cf9d1cbb3e6566352b64ca5ac7d0d0a5382e","raw_text_bytes":3348,"metadata_sha256":"5a8b712da81fb4eef8cc872923fcc99cbb3b1324217eef8d7eb2be3fcaa6d9b8","metadata_bytes":23032},{"reference_sha256":"6ca1a6305b2ba266e45437885ef7d46764e673246e18cf9542901f9a75dff60a","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-21T00:44:45.331Z","text_sha256":"dff43dde0d6312ae46e1bb0c2c51f960eea66831e51238e5790eff99a5d6671c","raw_text_sha256":"5533e20f4bc7ef9552c20771c15bf488bb91a7ae555dc4308112128038a7f841","raw_text_bytes":3348,"metadata_sha256":"c1e998125e0fe846a2ccd93c0d7719db7e09af3999ad40d06c31e15aa2245622","metadata_bytes":23031},{"reference_sha256":"ebb38d5394461e758ae6eabb64cb98ea91d81f1bf0bf016d04b16deff9a3893d","source_id":"39685b8a-3ad9-41c5-834b-b2aaafb2b0e5","captured_at":"2026-10-23T00:41:56.110Z","text_sha256":"26707074e3a0f99a8c7acd1b8aa912f4cdd4e23ba586bf0c6108f67c23e805ef","raw_text_sha256":"08e639fab80ae435845ac7aa21389d3afb2d69a3ee089d401be454426870db55","raw_text_bytes":3348,"metadata_sha256":"73cda7d948f1a36100270b6113755c017b22df59fda98b0074e8122a0b2afda0","metadata_bytes":23032}]}$policy$::jsonb;
$body$;
create function private.awardping_smart_legacy_manual_context(p_source uuid)returns jsonb
 language plpgsql stable security invoker set search_path=''set timezone='UTC'as $$
declare p jsonb:=private.awardping_smart_legacy_manual_policy();sp jsonb;wanted jsonb;cr public.shared_award_visual_review_candidates%rowtype;
 sr public.shared_award_sources%rowtype;ep uuid;ids uuid[];reserve_ids uuid[];rs public.gemini_spend_reservations%rowtype;
 rows jsonb:='[]';ledgers jsonb:='[]';ev jsonb;workers jsonb;roles jsonb;members jsonb;reg jsonb;exclusions jsonb;claim_proofs jsonb:='[]';ctx jsonb;
begin
 select value into sp from jsonb_array_elements(p->'sources')where value->>'id'=p_source::text;
 if sp is null then raise exception 'Unsupported SMART source.'using errcode='23514';end if;
 select*into strict sr from public.shared_award_sources where id=p_source;
 select epoch into strict ep from public.program_text_source_authority_epochs where active;
 if sr.shared_award_id::text is distinct from sp->>'owner'or sr.url is distinct from sp->>'url'or sr.page_type is distinct from sp->>'type'
  or sr.title is distinct from(case when sr.id='2562f7c2-4709-4d63-ac25-c4638733a981'::uuid then 'How to Submit your SMART Application'else 'application instructions'end)
  or sr.admin_review_status is distinct from'open'or sr.text_monitoring_state is distinct from sp->'state'or ep::text is distinct from p->>'epoch'
  or private.awardping_program_text_source_access(sr.id,'smart',ep)is distinct from true
  or private.awardping_program_source_allowed(sr.id)is distinct from true
 then raise exception 'Current SMART source, epoch or collection authority changed.'using errcode='40001';end if;
 select to_jsonb(r)into strict reg from public.stage1_award_registry r where cohort_key='smart';
 select jsonb_agg(to_jsonb(m)order by shared_award_id)into members from public.stage1_award_members m where cohort_key='smart';
 select jsonb_agg(to_jsonb(r)order by source_role)into roles from public.program_text_source_roster r where cohort_key='smart';
 select coalesce(jsonb_agg(to_jsonb(r)order by id),'[]'::jsonb)into exclusions from public.stage1_award_source_identity_rules r where cohort_key='smart';
 if reg->>'canonical_shared_award_id'is distinct from'd7d4d117-f312-456f-a75c-3dbd5d372c99'
  or not exists(select 1 from jsonb_array_elements(members)m where m->>'shared_award_id'=sr.shared_award_id::text and m->>'member_kind'='alias')
  or jsonb_array_length(roles)is distinct from 8 or not exists(select 1 from jsonb_array_elements(roles)r where r->'source_ids'@>jsonb_build_array(sr.id::text))
 then raise exception 'Current SMART alias membership or role coverage changed.'using errcode='40001';end if;
 select array_agg((value->>'id')::uuid order by value->>'id')into ids from jsonb_array_elements(p->'rows')where value->>'source_id'=p_source::text;
 if cardinality(ids)is distinct from 18 or exists(select 1 from public.shared_award_visual_review_candidates c where c.shared_award_source_id=p_source
  and c.status not in('rejected','published','superseded')and not(c.id=any(ids)))
 then raise exception 'Unknown or incomplete nonterminal SMART work.'using errcode='40001';end if;
 for wanted in select value from jsonb_array_elements(p->'rows')where value->>'source_id'=p_source::text order by value->>'id'loop
  select*into strict cr from public.shared_award_visual_review_candidates where id=(wanted->>'id')::uuid;
  if cr.shared_award_source_id<>p_source or cr.candidate_scope<>'content_change'or cr.status is distinct from wanted->>'status'
   or encode(extensions.digest(convert_to(to_jsonb(cr)::text,'UTF8'),'sha256'),'hex')is distinct from wanted->>'current_full_row_pg_sha256'
   or cr.publication_claim_token is not null or cr.publication_claimed_at is not null
  then raise exception 'Original whole candidate version or publication ownership changed.'using errcode='40001';end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('row',to_jsonb(cr),'pg_preimage_hash',wanted->>'current_full_row_pg_sha256',
   'xmin',(select xmin::text from public.shared_award_visual_review_candidates where id=cr.id)));
 end loop;
 -- Include metadata candidate inventories, not just candidate back-links. An
 -- orphan/new paid reservation must hold even if it was never written to a row.
 select array_agg(r.id order by r.id)into reserve_ids from public.gemini_spend_reservations r where
  (r.metadata->'candidate_ids')?|array(select x::text from unnest(ids)x)
  or exists(select 1 from public.shared_award_visual_review_candidates c where c.id=any(ids)and
   (r.id::text=c.worker_metadata->>'gemini_spend_reservation_id'or r.reservation_key=c.worker_metadata->>'gemini_spend_reservation_key'
    or r.provider_batch_name=c.gemini_batch_name or r.metadata->>'claim_token'=c.worker_metadata->>'submission_claim_token'));
 if cardinality(reserve_ids)is distinct from 3 or exists(select 1 from public.gemini_paid_retry_approvals where candidate_id=any(ids))
 then raise exception 'Unknown provider ownership or paid retry history needs review.'using errcode='40001';end if;
 for rs in select*from public.gemini_spend_reservations where id=any(reserve_ids)order by id loop
  select value into wanted from jsonb_array_elements(p->'reservations')where value->>'id'=rs.id::text;
  if wanted is null or rs.status<>'settled'or rs.spent_source is distinct from'terminal_provider_usage'
   or encode(extensions.digest(convert_to(to_jsonb(rs)::text,'UTF8'),'sha256'),'hex')is distinct from wanted->>'pg_preimage_hash'
   or (rs.usage->>'terminal_state'in('BATCH_STATE_SUCCEEDED','JOB_STATE_SUCCEEDED'))is distinct from true
   or rs.usage#>'{coverage,complete}'is distinct from'true'::jsonb or rs.usage#>'{coverage,mapping_complete}'is distinct from'true'::jsonb
   or rs.usage#>'{coverage,expected_responses}'is distinct from to_jsonb(rs.request_count)
   or rs.usage#>'{coverage,observed_responses}'is distinct from to_jsonb(rs.request_count)
   or rs.usage#>'{coverage,responses_with_usage}'is distinct from to_jsonb(rs.request_count)
  then raise exception 'Terminal complete provider usage is unconfirmed.'using errcode='40001';end if;
  ledgers:=ledgers||jsonb_build_array(jsonb_build_object('row',to_jsonb(rs),'pg_preimage_hash',encode(extensions.digest(convert_to(to_jsonb(rs)::text,'UTF8'),'sha256'),'hex')));
 end loop;
 select jsonb_agg(to_jsonb(e)order by id)into ev from public.gemini_spend_events e where reservation_id=any(reserve_ids);
 if ev is distinct from p->'events'then raise exception 'Original append-only provider events changed.'using errcode='40001';end if;
 for cr in select*from public.shared_award_visual_review_candidates where id=any(ids)and status='succeeded'order by id loop
  select*into strict rs from public.gemini_spend_reservations where id::text=cr.worker_metadata->>'gemini_spend_reservation_id';
  if rs.reservation_key is distinct from cr.worker_metadata->>'gemini_spend_reservation_key'
   or rs.provider_batch_name is distinct from cr.gemini_batch_name or rs.provider_batch_name is distinct from cr.worker_metadata->>'possible_external_batch_name'
   or rs.metadata->>'claim_token'is distinct from cr.worker_metadata->>'submission_claim_token'
   or not(rs.metadata->'candidate_ids'@>jsonb_build_array(cr.id::text))
   or cr.ai_result->>'finish_reason'is distinct from'STOP'or cr.ai_result->'provider_candidate_count'is distinct from'1'::jsonb
   or cr.ai_result->'is_true_change'is distinct from'false'::jsonb
  then raise exception 'Saved response and actual terminal submission binding disagree.'using errcode='40001';end if;
  claim_proofs:=claim_proofs||jsonb_build_array(jsonb_build_object('candidate_id',cr.id,'submission_token_sha256',
   encode(extensions.digest(convert_to(cr.worker_metadata->>'submission_claim_token','UTF8'),'sha256'),'hex'),
   'reservation_id',rs.id,'ownership_check_pg_hash',encode(extensions.digest(convert_to(jsonb_build_object('candidate',to_jsonb(cr),'reservation',to_jsonb(rs),'events',ev)::text,'UTF8'),'sha256'),'hex')));
 end loop;
 if jsonb_array_length(claim_proofs)<>3 then raise exception 'Expected3 fully bound saved responses.'using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'status',w.status,'started_at',w.started_at,'finished_at',w.finished_at)order by w.id),'[]'::jsonb)
 into workers from public.local_worker_runs w where w.id::text in(
  select worker_metadata->>'worker_run_id'from public.shared_award_visual_review_candidates where id=any(ids)
  union select worker_run_id::text from public.gemini_spend_reservations where id=any(reserve_ids));
 if exists(select 1 from jsonb_array_elements(workers)w where w->>'status'='running')then raise exception 'Related worker is still running.'using errcode='40001';end if;
 ctx:=jsonb_build_object('source',to_jsonb(sr),'source_xmin',(select xmin::text from public.shared_award_sources where id=sr.id),'epoch',ep,
  'registry',reg,'members',members,'roles',roles,'exclusions',exclusions,'candidate_rows',rows,'provider_reservations',ledgers,
  'spend_events',ev,'historical_submission_claims',claim_proofs,'related_workers',workers,'source_access',true,'unknown_nonterminal_count',0);
 return ctx;
end;$$;

create function public.inspect_smart_legacy_text_reconciliation(p_source uuid)returns jsonb language plpgsql stable security invoker set search_path=''set timezone='UTC'as $$
declare prior public.program_text_smart_legacy_manual_reviews%rowtype;ctx jsonb;
begin
 select*into prior from public.program_text_smart_legacy_manual_reviews where source_id=p_source and policy='awardping.smart-legacy36-manual-text-reconciliation.v1';
 if found then return jsonb_build_object('schema','awardping.smart-legacy36-resolution-receipt.v1','resolved',true,'current_authority_granted',false,'already_resolved',true,'source_id',p_source,'review_id',prior.id,'approved_at',prior.approved_at,'request',prior.request,
  'entry_ids',(select jsonb_agg(id order by candidate_id)from public.program_text_smart_legacy_manual_entries where review_id=prior.id));end if;
 ctx:=private.awardping_smart_legacy_manual_context(p_source);
 return jsonb_build_object('schema','awardping.smart-legacy36-sql-inspection.v1','already_resolved',false,'context',ctx,'context_hash',encode(extensions.digest(convert_to(ctx::text,'UTF8'),'sha256'),'hex'));
end;$$;

create function private.awardping_smart_legacy_manual_originals(p_source uuid,p_originals jsonb)returns jsonb language plpgsql stable security invoker set search_path=''set timezone='UTC'as $$
declare p jsonb:=private.awardping_smart_legacy_manual_policy();doc jsonb;pin jsonb;ref jsonb;meta jsonb;txt text;raw_text bytea;raw_meta bytea;out_docs jsonb:='[]';
begin
 if jsonb_typeof(p_originals)is distinct from'array'or jsonb_array_length(p_originals)<>19 or octet_length(p_originals::text)>1000000
 then raise exception 'Exactly19 complete source originals are required.'using errcode='23514';end if;
 for doc in select value from jsonb_array_elements(p_originals)loop
  if private.awardping_program_exact_object(doc,array['reference','text_raw_base64','metadata_raw_base64'])is distinct from true
   or jsonb_typeof(doc->'text_raw_base64')is distinct from'string'or length(doc->>'text_raw_base64')>16384
   or jsonb_typeof(doc->'metadata_raw_base64')is distinct from'string'or length(doc->>'metadata_raw_base64')>65536
  then raise exception 'Original byte document shape is invalid.'using errcode='23514';end if;
  ref:=doc->'reference';select value into pin from jsonb_array_elements(p->'originals')where value->>'source_id'=p_source::text
   and value->>'metadata_sha256'=ref#>>'{local_paths,meta,sha256}';
  if pin is null or not exists(select 1 from public.shared_award_visual_review_candidates c where c.shared_award_source_id=p_source
   and(ref=c.previous_snapshot_ref or ref=c.new_snapshot_ref))
  then raise exception 'Original reference is not bound to the selected historical source.'using errcode='23514';end if;
  raw_text:=decode(doc->>'text_raw_base64','base64');raw_meta:=decode(doc->>'metadata_raw_base64','base64');
  if octet_length(raw_text)is distinct from(pin->>'raw_text_bytes')::integer or octet_length(raw_meta)is distinct from(pin->>'metadata_bytes')::integer
   or encode(extensions.digest(raw_text,'sha256'),'hex')is distinct from pin->>'raw_text_sha256'
   or encode(extensions.digest(raw_meta,'sha256'),'hex')is distinct from pin->>'metadata_sha256'
  then raise exception 'Immutable original bytes changed.'using errcode='23514';end if;
  txt:=convert_from(raw_text,'UTF8');meta:=convert_from(raw_meta,'UTF8')::jsonb;
  if right(txt,1)is distinct from E'\n'or encode(extensions.digest(convert_to(left(txt,length(txt)-1),'UTF8'),'sha256'),'hex')is distinct from pin->>'text_sha256'
   or meta#>>'{source,id}'is distinct from p_source::text or meta#>>'{source,shared_award_id}'is distinct from'1efa2a75-e6b8-4bf6-80be-85ef2f6b3108'
   or meta#>>'{source,url}'is distinct from ref->>'final_url'
   or meta#>>'{source,page_type}'is distinct from(case when p_source='2562f7c2-4709-4d63-ac25-c4638733a981'::uuid then 'application'else 'deadline'end)
   or meta->>'final_url'is distinct from ref->>'final_url'or meta->>'page_title'is distinct from ref->>'page_title'or meta->>'captured_at'is distinct from ref->>'captured_at'
   or meta->>'text_hash'is distinct from ref->>'text_hash'or meta->'text_length'is distinct from to_jsonb(private.awardping_program_utf16_length(left(txt,length(txt)-1)))
   or meta->'expansion_state_capture_complete'is distinct from'true'::jsonb or meta->'expansion_state_truncated'is distinct from'false'::jsonb
   or meta->>'body_text_hash'is distinct from meta->>'text_hash'or meta->'body_text_length'is distinct from meta->'text_length'
   or meta->'expansion_state_failures'is distinct from'[]'::jsonb or meta->>'expansion_state_error'is not null
   or meta#>'{scroll_activation,hit_step_limit}'is distinct from'false'::jsonb
   or meta#>'{page_settle,stable}'is distinct from'true'::jsonb or meta#>'{page_settle,timed_out}'is distinct from'false'::jsonb
  then raise exception 'Original text, identity, framing or declared completeness is invalid.'using errcode='23514';end if;
  if exists(select 1 from jsonb_array_elements(out_docs)d where d->>'metadata_sha256'=pin->>'metadata_sha256')then raise exception 'Duplicate original.'using errcode='23514';end if;
  out_docs:=out_docs||jsonb_build_array(jsonb_build_object('reference',ref,'metadata_sha256',pin->>'metadata_sha256','text',left(txt,length(txt)-1),
   'original_bytes',doc));
 end loop;
 return out_docs;
end;$$;

create function public.approve_smart_legacy_text_reconciliation(p_source uuid,p_context_hash text,p_request jsonb,p_originals jsonb,p_actor uuid)returns jsonb
 language plpgsql security definer set search_path=''set timezone='UTC'as $$
<<manual_commit>>
declare prior public.program_text_smart_legacy_manual_reviews%rowtype;ctx jsonb;ctx_hash text;request_hash text;originals_hash text;docs jsonb;d jsonb;row_doc jsonb;cr public.shared_award_visual_review_candidates%rowtype;
 before_row jsonb;after_row jsonb;old_text text;new_text text;old_lines text[];new_lines text[];i integer;changed integer;review_id uuid:=gen_random_uuid();entry_id uuid;at_time timestamptz:=clock_timestamp();n integer;
begin
 if p_source not in('2562f7c2-4709-4d63-ac25-c4638733a981'::uuid,'39685b8a-3ad9-41c5-834b-b2aaafb2b0e5'::uuid)or p_source is null
  or p_actor is null or not exists(select 1 from auth.users where id=p_actor)
  or coalesce(p_context_hash,'')!~'^[a-f0-9]{64}$'or private.awardping_program_exact_object(p_request,array['source_id','preview_sha256','decisions'])is distinct from true
  or p_request->>'source_id'is distinct from p_source::text or coalesce(p_request->>'preview_sha256','')!~'^[a-f0-9]{64}$'
  or jsonb_typeof(p_request->'decisions')is distinct from'array'or jsonb_array_length(p_request->'decisions')<>18 or octet_length(p_request::text)>65536
  or jsonb_typeof(p_originals)is distinct from'array'or jsonb_array_length(p_originals)<>19 or octet_length(p_originals::text)>1000000
 then raise exception 'Exact authenticated manual source review required.'using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('stage1-national-25-release',0));
 request_hash:=encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex');
 originals_hash:=encode(extensions.digest(convert_to(p_originals::text,'UTF8'),'sha256'),'hex');
 select*into prior from public.program_text_smart_legacy_manual_reviews where source_id=p_source and policy='awardping.smart-legacy36-manual-text-reconciliation.v1';
 if found then
  if prior.context_hash is distinct from p_context_hash or prior.request_hash is distinct from request_hash or prior.originals_hash is distinct from originals_hash or prior.request is distinct from p_request
  then raise exception 'Different manual resolution already exists.'using errcode='40001';end if;
  return public.inspect_smart_legacy_text_reconciliation(p_source);
 end if;
 perform 1 from public.shared_award_sources where id=p_source for update nowait;
 perform 1 from public.program_text_source_roster where cohort_key='smart'order by source_role for share nowait;
 perform 1 from public.stage1_award_registry where cohort_key='smart'for share nowait;
 perform 1 from public.stage1_award_members where cohort_key='smart'order by shared_award_id for share nowait;
 perform 1 from public.program_text_source_authority_epochs where active for share nowait;
 perform 1 from public.shared_award_visual_review_candidates where shared_award_source_id=p_source order by id for update nowait;
 -- Terminal ledgers are never altered; sharing locks prevent a concurrent
 -- ownership change while exact fingerprints are checked a second time.
 perform 1 from public.gemini_spend_reservations where id in(select(value->>'id')::uuid from jsonb_array_elements(private.awardping_smart_legacy_manual_policy()->'reservations'))order by id for share nowait;
 ctx:=private.awardping_smart_legacy_manual_context(p_source);ctx_hash:=encode(extensions.digest(convert_to(ctx::text,'UTF8'),'sha256'),'hex');
 if ctx_hash is distinct from p_context_hash then raise exception 'Source/role/whole-row/provider context changed after preview.'using errcode='40001';end if;
 docs:=private.awardping_smart_legacy_manual_originals(p_source,p_originals);
 if(select count(distinct x->>'candidate_id')from jsonb_array_elements(p_request->'decisions')x)<>18
 then raise exception 'Every candidate requires a separate decision.'using errcode='23514';end if;
 -- Complete all per-row decisions before the first journal/candidate write.
 if exists(select 1 from jsonb_array_elements(p_request->'decisions')item where
  private.awardping_program_exact_object(item,array['candidate_id','decision','reason'])is distinct from true
  or item->>'decision'is distinct from'no_program_detail_change'or jsonb_typeof(item->'reason')is distinct from'string'
  or private.awardping_program_utf16_length(btrim(item->>'reason'))not between 20 and 2000
  or btrim(item->>'reason')is distinct from item->>'reason'
  or not exists(select 1 from jsonb_array_elements(ctx->'candidate_rows')r where r#>>'{row,id}'=item->>'candidate_id'))
 then raise exception 'All18 exact manual decisions must pass preflight.'using errcode='23514';end if;
 insert into public.program_text_smart_legacy_manual_reviews(id,source_id,epoch,policy,context_hash,request_hash,originals_hash,request,authority_before,verified_originals,actor_id,approved_at)
 values(review_id,p_source,(ctx->>'epoch')::uuid,'awardping.smart-legacy36-manual-text-reconciliation.v1',ctx_hash,request_hash,originals_hash,p_request,ctx,docs,p_actor,at_time);
 for row_doc in select value from jsonb_array_elements(ctx->'candidate_rows')order by value#>>'{row,id}'loop
  before_row:=row_doc->'row';select value into d from jsonb_array_elements(p_request->'decisions')where value->>'candidate_id'=before_row->>'id';
  if d is null or private.awardping_program_exact_object(d,array['candidate_id','decision','reason'])is distinct from true
   or d->>'decision'is distinct from'no_program_detail_change'or jsonb_typeof(d->'reason')is distinct from'string'
   or private.awardping_program_utf16_length(btrim(d->>'reason'))not between 20 and 2000 or btrim(d->>'reason')is distinct from d->>'reason'
  then raise exception 'Explicit bounded per-row manual reason required.'using errcode='23514';end if;
  select x->>'text'into strict old_text from jsonb_array_elements(docs)x where x->'reference'=before_row->'previous_snapshot_ref';
  select x->>'text'into strict new_text from jsonb_array_elements(docs)x where x->'reference'=before_row->'new_snapshot_ref';
  if before_row#>>'{prompt_payload,previous_text_excerpt}'is distinct from old_text||E'\n'
   or before_row#>>'{prompt_payload,new_text_excerpt}'is distinct from new_text then raise exception 'Complete saved prompt differs from originals.'using errcode='23514';end if;
  old_lines:=string_to_array(old_text,E'\n');new_lines:=string_to_array(new_text,E'\n');changed:=0;
  if cardinality(old_lines)<>cardinality(new_lines)then raise exception 'Historical whole-text line inventory changed.'using errcode='23514';end if;
  for i in 1..cardinality(old_lines)loop
   if old_lines[i]is distinct from new_lines[i]then
    changed:=changed+1;
    if old_lines[i]!~'^APPLICATION CLOSES IN: DAYS[0-9]+ HOURS[0-9]+ MINUTES[0-9]+$'
     or new_lines[i]!~'^APPLICATION CLOSES IN: DAYS[0-9]+ HOURS[0-9]+ MINUTES[0-9]+$'
    then raise exception 'Non-countdown historical text needs unresolved review.'using errcode='23514';end if;
   end if;
  end loop;
  if changed<>1 then raise exception 'Exactly one strict countdown line must differ.'using errcode='23514';end if;
  entry_id:=gen_random_uuid();
  insert into public.program_text_smart_legacy_manual_entries(id,review_id,candidate_id,original_candidate,original_pg_hash,original_xmin,decision,reason)
  values(entry_id,review_id,(before_row->>'id')::uuid,before_row,row_doc->>'pg_preimage_hash',row_doc->>'xmin','no_program_detail_change',d->>'reason');
  update public.shared_award_visual_review_candidates c set status='rejected',rejection_reason='admin_reviewed_no_program_detail_change',completed_at=at_time,updated_at=at_time,
   worker_metadata=c.worker_metadata||jsonb_build_object('smart_legacy_manual_reconciliation',jsonb_build_object('review_id',review_id,'entry_id',entry_id,'policy','awardping.smart-legacy36-manual-text-reconciliation.v1'))
  where c.id=(before_row->>'id')::uuid and to_jsonb(c)=before_row and c.xmin::text=row_doc->>'xmin';
  get diagnostics n=row_count;if n<>1 then raise exception 'Candidate changed before manual disposition.'using errcode='40001';end if;
  select to_jsonb(c)into after_row from public.shared_award_visual_review_candidates c where c.id=(before_row->>'id')::uuid;
  if(after_row-array['status','rejection_reason','completed_at','updated_at','worker_metadata'])is distinct from(before_row-array['status','rejection_reason','completed_at','updated_at','worker_metadata'])
   or(after_row->'worker_metadata')-'smart_legacy_manual_reconciliation'is distinct from before_row->'worker_metadata'
  then raise exception 'Manual disposition altered preserved original fields.'using errcode='23514';end if;
 end loop;
 -- Construct the new receipt in this VOLATILE writer; do not depend on a
 -- nested STABLE inspector seeing writes from its enclosing statement.
 return jsonb_build_object('schema','awardping.smart-legacy36-resolution-receipt.v1','current_authority_granted',false,'already_resolved',false,'resolved',true,'source_id',p_source,'review_id',review_id,'approved_at',at_time,
  'entry_ids',(select jsonb_agg(e.id order by e.candidate_id)from public.program_text_smart_legacy_manual_entries e where e.review_id=manual_commit.review_id));
end;$$;

revoke all on function private.awardping_smart_legacy_manual_immutable()from public,anon,authenticated,service_role;
revoke all on function private.awardping_smart_legacy_manual_policy()from public,anon,authenticated;
revoke all on function private.awardping_smart_legacy_manual_context(uuid)from public,anon,authenticated;
revoke all on function private.awardping_smart_legacy_manual_originals(uuid,jsonb)from public,anon,authenticated;
revoke all on function public.inspect_smart_legacy_text_reconciliation(uuid)from public,anon,authenticated;
revoke all on function public.approve_smart_legacy_text_reconciliation(uuid,text,jsonb,jsonb,uuid)from public,anon,authenticated;
grant execute on function private.awardping_smart_legacy_manual_policy(),private.awardping_smart_legacy_manual_context(uuid),private.awardping_smart_legacy_manual_originals(uuid,jsonb),
 public.inspect_smart_legacy_text_reconciliation(uuid),public.approve_smart_legacy_text_reconciliation(uuid,text,jsonb,jsonb,uuid)to service_role;

NOTIFY pgrst, 'reload schema';
